using System.Net;
using System.Security.Claims;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.Data.Sqlite;

namespace CltPlusPlus.Employee;

public static class VirtualMagistrateHearings
{
    public static void Map(WebApplication app)
    {
        EnsureSchema(app.Configuration);

        app.MapGet("/magistrate/standby", async (HttpContext ctx, IAntiforgery anti) =>
        {
            if (!CanMagistrate(ctx.User)) return Results.Forbid();
            var token=anti.GetAndStoreTokens(ctx).RequestToken!;
            var current=await GetStandby(app.Configuration,ctx.User.Identity?.Name??"");
            return Html(Page("Magistrate standby",$"""<main class='wrap'><a class='back' href='/'>← Home</a><section class='page-head'><div><span class='eyebrow'>MAGISTRATE · VIRTUAL HEARINGS</span><h1>Standby availability</h1><p>Mark yourself available for on-demand officer hearings.</p></div></section><section class='card'><p>Status: <b>{H(current?"Available":"Unavailable")}</b></p><form method='post' action='/magistrate/standby'><input type='hidden' name='__RequestVerificationToken' value='{H(token)}'/><input type='hidden' name='available' value='{(!current).ToString().ToLowerInvariant()}'/><button>{(current?"Go unavailable":"Stand by now")}</button></form></section></main>"""));
        }).RequireAuthorization();

        app.MapPost("/magistrate/standby", async (HttpContext ctx, IAntiforgery anti) =>
        {
            if(!CanMagistrate(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();var available=bool.TryParse(f["available"],out var a)&&a;await SetStandby(app.Configuration,ctx.User.Identity?.Name??"magistrate",available);return Results.Redirect("/magistrate/standby");
        }).RequireAuthorization();

        app.MapGet("/virtual-hearings/new", async (HttpContext ctx, IAntiforgery anti, Guid? expressReportId) =>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();var token=anti.GetAndStoreTokens(ctx).RequestToken!;var options=await ExpressOptions(app.Configuration,expressReportId);return Html(Page("Request virtual hearing",$"""<main class='wrap'><a class='back' href='/'>← Work queue</a><section class='card'><span class='eyebrow'>POLICE · VIRTUAL MAGISTRATE</span><h1>Request on-demand hearing</h1><div class='notice'><b>Recording notice</b><p>Audio/video recording is permitted only when the configured Jitsi service presents clear participant notice and recording is enabled through an approved Jibri/managed recording setup.</p></div><form method='post' action='/virtual-hearings'><input type='hidden' name='__RequestVerificationToken' value='{H(token)}'/><label>Express report<select name='expressReportId' required>{options}</select></label><label>Hearing purpose<textarea name='purpose' rows='4' required></textarea></label><button>Connect to available magistrate</button></form></section></main>"""));
        }).RequireAuthorization();

        app.MapPost("/virtual-hearings", async (HttpContext ctx, IAntiforgery anti) =>
        {
            if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var f=await ctx.Request.ReadFormAsync();if(!Guid.TryParse(f["expressReportId"],out var reportId))return Results.BadRequest("Express report is required.");var report=await LoadExpress(app.Configuration,reportId);if(report is null)return Results.BadRequest("Express report not found.");var magistrate=await FindAvailableMagistrate(app.Configuration);if(magistrate is null)return Results.Conflict(new{error="No magistrate is currently standing by."});var id=Guid.NewGuid();var now=DateTimeOffset.UtcNow.ToString("O");var room=$"cltpp-hearing-{id:N}";await using var cn=Open(app.Configuration);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="""INSERT INTO VirtualHearings(Id,HearingNumber,ExpressReportId,IncidentNumber,OfficerUsername,MagistrateUsername,Status,RoomName,Purpose,CreatedAt,UpdatedAt,RecordingStatus) VALUES($id,$num,$rid,$incident,$officer,$mag,'Assigned',$room,$purpose,$now,$now,'Not started')""";cmd.Parameters.AddWithValue("$id",id.ToString());cmd.Parameters.AddWithValue("$num",$"VMH-{DateTime.UtcNow:yyMMdd}-{Random.Shared.Next(100000,999999)}");cmd.Parameters.AddWithValue("$rid",reportId.ToString());cmd.Parameters.AddWithValue("$incident",report.Value.Number);cmd.Parameters.AddWithValue("$officer",ctx.User.Identity?.Name??"officer");cmd.Parameters.AddWithValue("$mag",magistrate);cmd.Parameters.AddWithValue("$room",room);cmd.Parameters.AddWithValue("$purpose",f["purpose"].ToString().Trim());cmd.Parameters.AddWithValue("$now",now);await cmd.ExecuteNonQueryAsync();await SetStandby(app.Configuration,magistrate,false);return Results.Redirect($"/virtual-hearings/{id}");
        }).RequireAuthorization();

        app.MapGet("/virtual-hearings/{id:guid}", async (Guid id,HttpContext ctx,IAntiforgery anti)=>
        {
            var hearing=await LoadHearing(app.Configuration,id);if(hearing is null)return Results.NotFound();var isOfficer=CanPolice(ctx.User)&&string.Equals(ctx.User.Identity?.Name,hearing.Value.Officer,StringComparison.OrdinalIgnoreCase);var isMag=CanMagistrate(ctx.User)&&string.Equals(ctx.User.Identity?.Name,hearing.Value.Magistrate,StringComparison.OrdinalIgnoreCase);var isAdmin=ctx.User.IsInRole("Administrator")||ctx.User.IsInRole("Supervisor");if(!isOfficer&&!isMag&&!isAdmin)return Results.Forbid();var report=await LoadExpress(app.Configuration,hearing.Value.ExpressReportId);if(report is null)return Results.NotFound();var token=anti.GetAndStoreTokens(ctx).RequestToken!;var evidence=await ExpressEvidence(app.Configuration,report.Value.Id);var jitsiDomain=app.Configuration["CLTPP_JITSI_DOMAIN"]??"meet.jit.si";var summary=isOfficer?$"""<section class='card'><h2>Officer hearing summary</h2><form method='post' action='/virtual-hearings/{id}/complete'><input type='hidden' name='__RequestVerificationToken' value='{H(token)}'/><label>Text summary<textarea name='summary' rows='8' required>{H(hearing.Value.OfficerSummary)}</textarea></label><label>Recording reference / URL<input name='recordingReference' value='{H(hearing.Value.RecordingReference)}'/></label><button>Complete hearing record</button></form></section>""":"";return Html(Page(hearing.Value.Number,$"""<main class='wrap'><a class='back' href='/'>← Home</a><section class='page-head'><div><span class='eyebrow'>VIRTUAL MAGISTRATE · {H(hearing.Value.Status)}</span><h1>{H(hearing.Value.Number)}</h1><p>Express report {H(report.Value.Number)}</p></div></section><div class='notice'><b>Linked Express Report</b><p>The magistrate has read-only access to the full report context for this hearing.</p></div><div class='detail-grid'><section class='card'><h2>Hearing</h2><dl><dt>Officer</dt><dd>{H(hearing.Value.Officer)}</dd><dt>Magistrate</dt><dd>{H(hearing.Value.Magistrate)}</dd><dt>Purpose</dt><dd>{H(hearing.Value.Purpose)}</dd><dt>Room</dt><dd>{H(hearing.Value.Room)}</dd><dt>Recording status</dt><dd>{H(hearing.Value.RecordingStatus)}</dd></dl><div id='jitsi' style='min-height:520px'></div></section><aside><section class='card'><h2>Express report details</h2><dl><dt>Report</dt><dd>{H(report.Value.Number)}</dd><dt>Status</dt><dd>{H(report.Value.Status)}</dd><dt>Title</dt><dd>{H(report.Value.Title)}</dd><dt>Location</dt><dd>{H(report.Value.Location)}</dd><dt>Created by</dt><dd>{H(report.Value.CreatedBy)}</dd><dt>Created</dt><dd>{H(report.Value.CreatedAt)}</dd><dt>Submitted by</dt><dd>{H(report.Value.SubmittedBy)}</dd><dt>Submitted</dt><dd>{H(report.Value.SubmittedAt)}</dd></dl><h3>Transcript / narrative</h3><p style='white-space:pre-wrap'>{H(report.Value.Transcript)}</p><h3>Evidence</h3>{evidence}</section></aside></div>{summary}<script src='https://{H(jitsiDomain)}/external_api.js'></script><script>const api=new JitsiMeetExternalAPI('{Js(jitsiDomain)}',{{roomName:'{Js(hearing.Value.Room)}',parentNode:document.querySelector('#jitsi'),userInfo:{{displayName:'{Js(ctx.User.Identity?.Name??"participant")}'}}}});</script></main>"""));
        }).RequireAuthorization();

        app.MapPost("/virtual-hearings/{id:guid}/complete",async(Guid id,HttpContext ctx,IAntiforgery anti)=>{if(!CanPolice(ctx.User))return Results.Forbid();await anti.ValidateRequestAsync(ctx);var h=await LoadHearing(app.Configuration,id);if(h is null)return Results.NotFound();if(!string.Equals(h.Value.Officer,ctx.User.Identity?.Name,StringComparison.OrdinalIgnoreCase)&&!ctx.User.IsInRole("Supervisor")&&!ctx.User.IsInRole("Administrator"))return Results.Forbid();var f=await ctx.Request.ReadFormAsync();var summary=f["summary"].ToString().Trim();if(summary.Length==0)return Results.BadRequest("Officer summary is required.");await using var cn=Open(app.Configuration);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="UPDATE VirtualHearings SET Status='Completed',OfficerSummary=$s,RecordingReference=$r,RecordingStatus=CASE WHEN $r='' THEN RecordingStatus ELSE 'Recorded' END,CompletedAt=$u,UpdatedAt=$u WHERE Id=$id";cmd.Parameters.AddWithValue("$s",summary);cmd.Parameters.AddWithValue("$r",f["recordingReference"].ToString().Trim());cmd.Parameters.AddWithValue("$u",DateTimeOffset.UtcNow.ToString("O"));cmd.Parameters.AddWithValue("$id",id.ToString());await cmd.ExecuteNonQueryAsync();return Results.Redirect($"/virtual-hearings/{id}");}).RequireAuthorization();
    }

    private static async Task<string> ExpressOptions(IConfiguration c,Guid? selected){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT Id,ReportNumber,COALESCE(Title,'') FROM ExpressReports ORDER BY UpdatedAt DESC LIMIT 100";var list=new List<string>();await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync()){var id=r.GetString(0);list.Add($"<option value='{H(id)}' {(selected?.ToString()==id?"selected":"")}>{H(r.GetString(1))} · {H(r.GetString(2))}</option>");}return string.Join("",list);}
    private static async Task<(Guid Id,string Number,string Status,string Title,string Transcript,string Location,string CreatedBy,string CreatedAt,string? SubmittedBy,string? SubmittedAt)?> LoadExpress(IConfiguration c,Guid id){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT Id,ReportNumber,Status,COALESCE(Title,''),COALESCE(Transcript,''),COALESCE(Location,''),CreatedBy,CreatedAt,SubmittedBy,SubmittedAt FROM ExpressReports WHERE Id=$id";cmd.Parameters.AddWithValue("$id",id.ToString());await using var r=await cmd.ExecuteReaderAsync();return await r.ReadAsync()?(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),N(r,8),N(r,9)):null;}
    private static async Task<string> ExpressEvidence(IConfiguration c,Guid id){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT OriginalName,ContentType,ByteLength,Sha256,UploadedBy,UploadedAt,OfficerNote FROM ExpressReportAttachments WHERE ExpressReportId=$id ORDER BY UploadedAt";cmd.Parameters.AddWithValue("$id",id.ToString());var rows=new List<string>();await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add($"<article><b>{H(r.GetString(0))}</b><small>{H(r.GetString(1))} · {r.GetInt64(2)} bytes · SHA-256 {H(r.GetString(3))}</small><p>{H(N(r,6))}</p><small>Uploaded by {H(r.GetString(4))} · {H(r.GetString(5))}</small></article>");return rows.Count==0?"<p class='muted'>No evidence attached.</p>":string.Join("",rows);}
    private static async Task<(Guid Id,string Number,Guid ExpressReportId,string Officer,string Magistrate,string Status,string Room,string Purpose,string RecordingStatus,string? RecordingReference,string? OfficerSummary)?> LoadHearing(IConfiguration c,Guid id){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT Id,HearingNumber,ExpressReportId,OfficerUsername,MagistrateUsername,Status,RoomName,Purpose,RecordingStatus,RecordingReference,OfficerSummary FROM VirtualHearings WHERE Id=$id";cmd.Parameters.AddWithValue("$id",id.ToString());await using var r=await cmd.ExecuteReaderAsync();return await r.ReadAsync()?(Guid.Parse(r.GetString(0)),r.GetString(1),Guid.Parse(r.GetString(2)),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),N(r,9),N(r,10)):null;}
    private static async Task<string?> FindAvailableMagistrate(IConfiguration c){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT Username FROM MagistrateStandby WHERE Available=1 ORDER BY UpdatedAt LIMIT 1";return (string?)await cmd.ExecuteScalarAsync();}
    private static async Task<bool> GetStandby(IConfiguration c,string user){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="SELECT Available FROM MagistrateStandby WHERE Username=$u";cmd.Parameters.AddWithValue("$u",user);var v=await cmd.ExecuteScalarAsync();return v is long l&&l==1;}
    private static async Task SetStandby(IConfiguration c,string user,bool available){await using var cn=Open(c);await cn.OpenAsync();var cmd=cn.CreateCommand();cmd.CommandText="INSERT INTO MagistrateStandby(Username,Available,UpdatedAt) VALUES($u,$a,$t) ON CONFLICT(Username) DO UPDATE SET Available=$a,UpdatedAt=$t";cmd.Parameters.AddWithValue("$u",user);cmd.Parameters.AddWithValue("$a",available?1:0);cmd.Parameters.AddWithValue("$t",DateTimeOffset.UtcNow.ToString("O"));await cmd.ExecuteNonQueryAsync();}
    private static void EnsureSchema(IConfiguration c){using var cn=Open(c);cn.Open();using var cmd=cn.CreateCommand();cmd.CommandText="""CREATE TABLE IF NOT EXISTS MagistrateStandby(Username TEXT PRIMARY KEY,Available INTEGER NOT NULL,UpdatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS VirtualHearings(Id TEXT PRIMARY KEY,HearingNumber TEXT NOT NULL UNIQUE,ExpressReportId TEXT NOT NULL,IncidentNumber TEXT NOT NULL,OfficerUsername TEXT NOT NULL,MagistrateUsername TEXT NOT NULL,Status TEXT NOT NULL,RoomName TEXT NOT NULL,Purpose TEXT NOT NULL,CreatedAt TEXT NOT NULL,UpdatedAt TEXT NOT NULL,CompletedAt TEXT NULL,OfficerSummary TEXT NULL,RecordingStatus TEXT NOT NULL,RecordingReference TEXT NULL);CREATE INDEX IF NOT EXISTS IX_VirtualHearings_ExpressReport ON VirtualHearings(ExpressReportId);CREATE INDEX IF NOT EXISTS IX_VirtualHearings_Status ON VirtualHearings(Status);""";cmd.ExecuteNonQuery();}
    private static SqliteConnection Open(IConfiguration c){var p=c["CLTPP_PUBLIC_SAFETY_DB"]??Path.Combine(AppContext.BaseDirectory,"data","public-safety.db");Directory.CreateDirectory(Path.GetDirectoryName(p)!);return new SqliteConnection($"Data Source={p}");}
    private static bool CanPolice(ClaimsPrincipal u)=>u.IsInRole("Administrator")||u.IsInRole("Supervisor")||u.FindAll(DepartmentAccess.ClaimType).Any(c=>string.Equals(c.Value,"Police",StringComparison.OrdinalIgnoreCase));
    private static bool CanMagistrate(ClaimsPrincipal u)=>u.IsInRole("Magistrate")||u.IsInRole("Administrator");
    private static string? N(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static string H(string? s)=>WebUtility.HtmlEncode(s??"");private static string Js(string s)=>s.Replace("\\","\\\\").Replace("'","\\'");
    private static IResult Html(string s)=>Results.Content(s,"text/html; charset=utf-8");private static string Page(string t,string b)=>$"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{H(t)} · CLT++ Employee</title><link rel='stylesheet' href='/app.css'></head><body><header class='top'><a href='/' class='brand'>CLT<span>++</span> <small>EMPLOYEE</small></a><div>Virtual magistrate hearings</div></header>{b}</body></html>";
}
